// Native tests: the 3D looks of the real faces (core/face3d_looks.h, data generated by scripts/gen_face3d_looks.py into
// core/face3d_looks_data.h from turbogui/data/face3d_looks.csv and the hand check data/face3d_looks_check.csv), their
// confidences (unsure values never match a filter) and the real-face chooser's 3D facets (core/face_filter.h).
// Included by test_main.cpp, run from main with the other core tests.
#pragma once
#include <algorithm>

#include "core/face3d_looks.h"
#include "core/face_filter.h"

static void test_face3d_looks() {
    using namespace turbo;
    run_case("3D looks: generated header = data/face3d_looks.csv + hand check (gen output parses, sorted, in range)", [] {
        auto table_ok = [](const face3d::Look* a, size_t n) {
            bool ok = true;
            for (size_t i = 0; i < n; ++i) {
                if (i && a[i - 1].id >= a[i].id) ok = false;
                for (int t = 0; t < face3d::kTraitCount; ++t)
                    if (a[i].v[t] >= face3d::value_count(t) || a[i].c[t] >= face3d::kConfCount) ok = false;
            }
            return ok;
        };
        const size_t n = face3d::count(), nc = face3d::check_count();
        CHECK(table_ok(face3d::all(), n) && n > 0, fmt("%zu looks, ids strictly ascending, every value and confidence in range", n));
        CHECK(table_ok(face3d::check_looks(), nc) && nc >= 140, fmt("hand check: %zu heads, ids ascending, values in range", nc));
        // the CSVs kept in the repo: every row parses with the generator's rules and is the compiled look / check
        const fs::path data = fs::path(g_lua).parent_path().parent_path().parent_path() / "data";
        auto compare = [](const fs::path& csv, const face3d::Look* table, size_t count, const char* what) {
            std::ifstream in(csv);
            CHECK(in.good(), csv.string());
            std::string line;
            size_t rows = 0, bad = 0, differ = 0, conf_rows = 0;
            std::getline(in, line);
            CHECK(line.rfind("id,skin,hair_colour,hair_length,hair_type,facial_hair,beard_colour,headwear,conf", 0) == 0, std::string(what) + " CSV header");
            while (std::getline(in, line)) {
                if (line.empty()) continue;
                face3d::Look l{};
                if (!face3d::parse_row(line, &l)) {
                    ++bad;
                    continue;
                }
                ++rows;
                conf_rows += std::count(line.begin(), line.end(), ',') == face3d::kTraitCount + 1 ? 1 : 0;
                const face3d::Look* end = table + count;
                const face3d::Look* c = std::lower_bound(table, end, l.id, [](const face3d::Look& x, int32_t v) { return x.id < v; });
                if (c == end || c->id != l.id || std::memcmp(c->v, l.v, sizeof(l.v)) != 0 || std::memcmp(c->c, l.c, sizeof(l.c)) != 0) ++differ;
            }
            CHECK(bad == 0 && rows == count && differ == 0 && conf_rows == rows,
                  fmt("%s: %zu CSV rows (%zu bad, %zu differ from the header, %zu with conf) for %zu entries", what, rows, bad, differ, conf_rows, count));
        };
        compare(data / "face3d_looks.csv", face3d::all(), n, "looks");
        compare(data / "face3d_looks_check.csv", face3d::check_looks(), nc, "hand check");
        // the hand check is a sample of the table: every checked head has a look, and the confidence note reads it
        size_t in_table = 0, unsure = 0, values = 0;
        for (size_t i = 0; i < nc; ++i) in_table += face3d::lookup(face3d::check_looks()[i].id) ? 1 : 0;
        for (size_t i = 0; i < n; ++i)
            for (int t = 0; t < face3d::kTraitCount; ++t, ++values) unsure += face3d::unsure(face3d::all()[i], t) ? 1 : 0;
        CHECK(in_table == nc && unsure > 0 && unsure * 4 < values, fmt("%zu of %zu checked heads in the table; %zu of %zu values unsure", in_table, nc, unsure, values));
        for (int f = faces::kSkin3d; f <= faces::kHeadwear3d; ++f) {
            const faces::CheckResult r = faces::check3d(static_cast<faces::Facet>(f));
            const std::string note = faces::check_note(static_cast<faces::Facet>(f));
            CHECK(r.heads == int(nc) && r.answered <= r.heads && r.right <= r.answered && r.right * 10 >= r.answered * 8 && r.answered * 10 >= r.heads * 8 &&
                      note.rfind("Hand check of " + std::to_string(nc) + " heads: ", 0) == 0,
                  fmt("%s: %d of %d answered right; %s", faces::facet_title(static_cast<faces::Facet>(f)), r.right, r.answered, note.c_str()));
        }
    });

    run_case("3D looks: CSV rows, names, lookup, describe", [] {
        face3d::Look l{};
        CHECK(face3d::parse_row("230666,light,dark_brown,short,wavy,short_beard,dark_brown,none\r", &l) && l.id == 230666 &&
                  l.v[face3d::kSkin] == face3d::kSkinLight && l.v[face3d::kHairColour] == face3d::kHairDarkBrown &&
                  l.v[face3d::kHairLength] == face3d::kShort && l.v[face3d::kHairType] == face3d::kWavy &&
                  l.v[face3d::kFacialHair] == face3d::kShortBeard && l.v[face3d::kBeardColour] == face3d::kBeardDarkBrown &&
                  l.v[face3d::kHeadwear] == face3d::kNoHeadwear,
              "a good row (CRLF)");
        CHECK(face3d::parse_row(" 7 , Very_Light ,NONE,bald,other,clean,none,hat", &l) && l.id == 7 && l.v[face3d::kSkin] == face3d::kSkinVeryLight &&
                  l.v[face3d::kHeadwear] == face3d::kHat,
              "spaces and case ignored");
        CHECK(!face3d::parse_row("id,skin,hair_colour,hair_length,hair_type,facial_hair,beard_colour,headwear", nullptr) &&
                  !face3d::parse_row("239807,light,light_brown,short,straight,stubble,light_brown,none", nullptr) &&  // no light_brown beard
                  !face3d::parse_row("1,light,black,short,wavy,clean,none", nullptr) &&                              // 7 columns
                  !face3d::parse_row("1,light,black,short,wavy,clean,none,none,x", nullptr) &&                       // bad conf
                  !face3d::parse_row("1,light,black,short,wavy,clean,none,none,hhhhhhx", nullptr) &&                 // bad conf letter
                  !face3d::parse_row("1,light,black,short,wavy,clean,none,none,hhhhhh", nullptr) &&                  // 6 letters
                  !face3d::parse_row("1,light,black,short,wavy,clean,none,none,hhhhhhh,h", nullptr) &&               // 10 columns
                  !face3d::parse_row("0,light,black,short,wavy,clean,none,none", nullptr) &&                         // id 0
                  !face3d::parse_row("-5,light,black,short,wavy,clean,none,none", nullptr) &&
                  !face3d::parse_row("99999999999,light,black,short,wavy,clean,none,none", nullptr) &&
                  !face3d::parse_row("12a,light,black,short,wavy,clean,none,none", nullptr) &&
                  !face3d::parse_row("", nullptr),
              "bad rows are refused (the generator skips them)");
        CHECK(std::string(face3d::value_name(face3d::kSkin, face3d::kSkinVeryLight)) == "Very light" &&
                  std::string(face3d::value_name(face3d::kHairColour, face3d::kHairDarkBrown)) == "Dark brown" &&
                  std::string(face3d::value_name(face3d::kFacialHair, face3d::kShortBeard)) == "Short beard" &&
                  std::string(face3d::value_name(face3d::kHeadwear, face3d::kHat)) == "Hat / cap" &&
                  std::string(face3d::value_name(face3d::kSkin, 6)) == "?" && std::string(face3d::trait_title(face3d::kHeadwear)) == "Headwear" &&
                  face3d::value_count(face3d::kHairType) == face3d::kMaxValues && face3d::value_count(face3d::kSkin) == 6 &&
                  face3d::parse_value(face3d::kHairColour, "dyed") == face3d::kHairDyed && face3d::parse_value(face3d::kHairColour, "pink") == -1,
              "readable names and words");
        const face3d::Look sample = {230666, {face3d::kSkinLight, face3d::kHairDarkBrown, face3d::kShort, face3d::kWavy, face3d::kShortBeard,
                                              face3d::kBeardDarkBrown, face3d::kNoHeadwear}};
        CHECK(face3d::describe(sample) == "light skin, dark brown short wavy hair, short beard (dark brown), no headwear", face3d::describe(sample));
        // confidences: 8 columns = sure everywhere; the 9th column gives one letter h / m / l per trait (case ignored)
        CHECK(face3d::parse_row("230666,light,dark_brown,short,wavy,short_beard,dark_brown,none", &l) &&
                  std::all_of(l.c, l.c + face3d::kTraitCount, [](uint8_t c) { return c == face3d::kConfHigh; }) &&
                  face3d::unsure_traits(l).empty(),
              "no conf column: every trait sure");
        CHECK(face3d::parse_row("5,olive,black,short,curly,stubble,black,none, hhhLmhl \r", &l) && l.id == 5 && l.c[face3d::kSkin] == face3d::kConfHigh &&
                  l.c[face3d::kHairType] == face3d::kConfLow && l.c[face3d::kFacialHair] == face3d::kConfMedium &&
                  l.c[face3d::kHeadwear] == face3d::kConfLow && face3d::unsure(l, face3d::kHairType) && !face3d::unsure(l, face3d::kFacialHair) &&
                  !face3d::unsure(l, face3d::kSkin) && !face3d::unsure(l, -1) && !face3d::unsure(l, face3d::kTraitCount),
              "conf letters: h sure, m probable, l unsure");
        CHECK(face3d::describe(l) == "olive skin, black short curly? hair, stubble (black), no headwear?" &&
                  face3d::unsure_traits(l) == "hair type, headwear",
              face3d::describe(l) + " / " + face3d::unsure_traits(l));
        CHECK(std::string(face3d::conf_name(face3d::kConfHigh)) == "sure" && std::string(face3d::conf_name(face3d::kConfLow)) == "unsure" &&
                  std::string(face3d::conf_name(3)) == "?",
              "confidence names");
        const face3d::Look bald = {8, {face3d::kSkinDark, face3d::kHairNone, face3d::kBald, face3d::kOtherType, face3d::kClean, face3d::kBeardNone,
                                       face3d::kHat}};
        CHECK(face3d::describe(bald) == "dark skin, bald, clean-shaven, hat / cap", face3d::describe(bald));
        // lookup: a test table instead of the generated one
        static const face3d::Look table[] = {{10, {0, 0, 0, 0, 0, 0, 0}}, {20, {1, 1, 1, 1, 1, 1, 1}}, {30, {2, 2, 2, 2, 2, 2, 2}}};
        const size_t generated = face3d::count();
        const uint64_t g0 = face3d::generation();
        face3d::use_table(table, 3);
        CHECK(face3d::count() == 3 && face3d::lookup(20) == &table[1] && face3d::lookup(10) == &table[0] && face3d::lookup(30) == &table[2] &&
                  !face3d::lookup(15) && !face3d::lookup(31) && !face3d::lookup(0) && !face3d::lookup(-1) && face3d::generation() != g0,
              "lookup: binary search, nullptr for an unclassified id");
        face3d::use_table(nullptr, 0);
        CHECK(face3d::count() == generated && face3d::all() != table, "generated table restored");
    });

    run_case("3D looks: unsure values never match a filter; facet_unknowns counts them; the hand check note", [] {
        using namespace faces;
        // 1 sure everywhere; 2 unsure of its skin and hair type; 3 has no look
        static const face3d::Look looks[] = {
            {1, {face3d::kSkinLight, face3d::kHairBlack, face3d::kShort, face3d::kCurly, face3d::kClean, face3d::kBeardNone, face3d::kNoHeadwear}},
            {2, {face3d::kSkinOlive, face3d::kHairBlack, face3d::kShort, face3d::kCurly, face3d::kStubble, face3d::kBeardBlack, face3d::kNoHeadwear},
             {face3d::kConfLow, face3d::kConfMedium, 0, face3d::kConfLow, 0, 0, 0}},
        };
        std::vector<Face> heads(3);
        for (int i = 0; i < 3; ++i) {
            heads[size_t(i)].id = i + 1;
            heads[size_t(i)].real = true;
            set_look(heads[size_t(i)], i < 2 ? &looks[i] : nullptr);
        }
        CHECK(heads[1].raw[kSkin3d] == kUnsure && heads[1].raw[kHairType3d] == kUnsure && heads[1].raw[kHairColour3d] == face3d::kHairBlack &&
                  heads[1].raw[kFacialHair3d] == face3d::kStubble && heads[2].raw[kSkin3d] == kUnclassified && heads[1].look == &looks[1],
              "set_look: unsure traits take kUnsure, a probable one keeps its value");
        Filter flt;
        for (int v = 0; v < group_count3d(kSkin3d); ++v) {
            flt.sel[kSkin3d] = v;
            CHECK(!matches(heads[1], flt), fmt("an unsure skin never matches skin group %d", v));
        }
        flt.clear();
        flt.sel[kHairColour3d] = facet_key(kHairColour3d, face3d::kHairBlack);
        CHECK(matches(heads[0], flt) && matches(heads[1], flt) && !matches(heads[2], flt), "a probable value matches");
        flt.clear();
        const std::vector<size_t> pool = {0, 1, 2};
        std::vector<Count> types = facet_counts(heads, pool, flt, kHairType3d);
        const Unknowns u = facet_unknowns(heads, pool, flt, kHairType3d);
        CHECK(types.size() == size_t(group_count3d(kHairType3d)) && types[size_t(facet_key(kHairType3d, face3d::kCurly))].n == 1 &&
                  u.unsure == 1 && u.unclassified == 1,
              fmt("hair type: curly 1, unsure %d, not classified %d", u.unsure, u.unclassified));
        flt.sel[kFacialHair3d] = facet_key(kFacialHair3d, face3d::kClean);  // the other filters narrow the unknown counts too
        const Unknowns u2 = facet_unknowns(heads, pool, flt, kHairType3d);
        CHECK(u2.unsure == 0 && u2.unclassified == 0 && facet_unknowns(heads, pool, Filter(), kGender).unsure == 0, "under the other filters");
        Face game;  // a game head without a look keeps kNoValue: counted as not classified
        game.game_head = true;
        std::vector<Face> with_game = {heads[0], game};
        CHECK(facet_unknowns(with_game, {0, 1}, Filter(), kSkin3d).unclassified == 1, "a game head without a look: not classified");
        CHECK(key_label(kSkin3d, kUnsure) == "unsure" && trait_label(kHairType3d, kUnsure) == "unsure", "labels");
        const std::string t2 = head_traits(heads[1], true);
        CHECK(t2.find("\n3D look: olive? skin, black short curly? hair, stubble (black), no headwear") == 0 &&
                  t2.find("\n? = unsure (no filter value matches it): skin tone, hair type") != std::string::npos &&
                  head_traits(heads[0], true).find("unsure") == std::string::npos,
              t2);
        // the hand check against the table: 1 right, 2 answered wrong in hair colour (dark brown is the Brown group),
        // unsure in skin; 9 has no look (not counted)
        static const face3d::Look checks[] = {
            {1, {face3d::kSkinLight, face3d::kHairBlack, face3d::kBuzz, face3d::kCurly, face3d::kClean, face3d::kBeardNone, face3d::kNoHeadwear}},
            {2, {face3d::kSkinBrown, face3d::kHairDarkBrown, face3d::kShort, face3d::kWavy, face3d::kStubble, face3d::kBeardBlack, face3d::kNoHeadwear}},
            {9, {0, 0, 0, 0, 0, 0, 0}},
        };
        face3d::use_table(looks, 2);
        face3d::use_check(checks, 3);
        const CheckResult skin = check3d(kSkin3d), colour = check3d(kHairColour3d), length = check3d(kHairLength3d), type = check3d(kHairType3d);
        CHECK(skin.heads == 2 && skin.answered == 1 && skin.right == 1 && colour.answered == 2 && colour.right == 1 && length.right == 1 &&
                  type.answered == 1 && type.right == 1 && check3d(kGender).heads == 0,
              "check3d: heads in the table, answered (not unsure), right in the filter group");
        CHECK(check_note(kSkin3d) == "Hand check of 2 heads: 100% in the right group, 50% unsure" &&
                  check_note(kHairColour3d) == "Hand check of 2 heads: 50% in the right group, 0% unsure" && check_note(kEyes).empty(),
              check_note(kSkin3d) + " / " + check_note(kHairColour3d));
        face3d::use_check(nullptr, 0);
        face3d::use_table(nullptr, 0);
        CHECK(face3d::check_looks() != checks && face3d::check_count() > 0, "generated hand check restored");
        face3d::use_check(checks, 0);
        CHECK(check_note(kSkin3d).empty(), "no hand check: no note");
        face3d::use_check(nullptr, 0);
    });

    run_case("Real-face chooser with 3D looks: 3D facets in at most 5 groups, 'not classified yet' no choice, database facets last", [] {
        using namespace faces;
        static const face3d::Look looks[] = {
            {1, {face3d::kSkinLight, face3d::kHairDarkBrown, face3d::kShort, face3d::kWavy, face3d::kShortBeard, face3d::kBeardDarkBrown, face3d::kNoHeadwear}},
            {2, {face3d::kSkinDark, face3d::kHairBlack, face3d::kShort, face3d::kAfro, face3d::kClean, face3d::kBeardNone, face3d::kNoHeadwear}},
            {3, {face3d::kSkinLight, face3d::kHairBlonde, face3d::kLong, face3d::kTied, face3d::kClean, face3d::kBeardNone, face3d::kHeadband}},
        };
        auto mk = [](int64_t id, int64_t gender, int64_t eyes, const face3d::Look* look) {
            Face f;
            f.id = id;
            f.headassetid = id;
            f.real = true;
            f.name = "P" + std::to_string(id);
            f.raw[kGender] = gender;
            f.raw[kEyes] = eyes;
            f.raw[kSkin] = 20;        // the database says Caucasian 2 for all: the 3D facets ignore it
            f.raw[kHairColour] = 3;   // Dark Brown
            f.raw[kEthnicity] = 34;
            set_look(f, look);
            return f;
        };
        std::vector<Face> heads = {mk(1, 0, 3, &looks[0]), mk(2, 0, 3, &looks[1]), mk(3, 1, 5, &looks[2]), mk(4, 0, 3, nullptr), mk(5, 1, 3, nullptr)};
        std::vector<size_t> pool = {0, 1, 2, 3, 4};
        CHECK(count_looks(heads) == 3 && heads[3].raw[kSkin3d] == kUnclassified && heads[0].raw[kHairType3d] == face3d::kWavy &&
                  heads[0].look == &looks[0] && !heads[4].look,
              "set_look: the look's values, kUnclassified without a look");
        // facets: Gender, the 7 3D facets, then Eyes / Ethnicity "(database)"; managers keep the database facets
        const Facet* o = facet_order(true);
        CHECK(facet_order_size(true) == 10 && o[0] == kGender && o[1] == kSkin3d && o[7] == kHeadwear3d && o[8] == kEyes && o[9] == kEthnicity,
              "3D facet order");
        CHECK(std::string(facet_title(kEyes, true)) == "Eyes (database)" && std::string(facet_title(kEthnicity, true)) == "Ethnicity (database)" &&
                  std::string(facet_title(kEyes, false)) == "Eyes" && std::string(facet_title(kSkin3d, true)) == "Skin tone" &&
                  std::string(facet_title(kHeadwear3d)) == "Headwear" && std::string(facet_title(kHairLength3d)) == "Hair length",
              "titles");
        CHECK(facet_order_size(false) == kDbFacetCount && !facet_shown(kSkin3d, false) && facet_shown(kHair, false) && !facet_shown(kHair, true) &&
                  !facet_shown(kHairColour, true) && facet_shown(kEyes, true) && facet_3d(kHeadwear3d) && !facet_3d(kGender) &&
                  std::string(facet_field(kSkin3d)).empty(),
              "database facets without 3D looks (managers)");
        CHECK(key_label(kHairColour3d, facet_key(kHairColour3d, face3d::kHairDarkBrown)) == "Brown" &&
                  trait_label(kHairColour3d, face3d::kHairDarkBrown) == "Dark brown" && key_label(kHeadwear3d, face3d::kHat) == "Hat / cap" &&
                  key_label(kFacialHair3d, kUnclassified) == "not classified yet" && trait_label(kFacialHair3d, face3d::kShortBeard) == "Short beard",
              "3D value labels");
        // a head with a look matches only its own values; a head without one never matches a 3D value filter
        Filter flt;
        flt.sel[kHairLength3d] = face3d::kShort;
        CHECK(matches(heads[0], flt) && matches(heads[1], flt) && !matches(heads[2], flt) && !matches(heads[3], flt) && !matches(heads[4], flt),
              "hair length short: 1 and 2 only");
        flt.sel[kHairType3d] = facet_key(kHairType3d, face3d::kWavy);
        CHECK(matches(heads[0], flt) && !matches(heads[1], flt), "short + wavy & curly: 1");
        flt.clear();
        for (int t = 0; t < face3d::kTraitCount; ++t)
            for (int v = 0; v < group_count3d(static_cast<Facet>(kSkin3d + t)); ++v) {
                flt.sel[kSkin3d + t] = v;
                CHECK(!matches(heads[3], flt) && !matches(heads[4], flt), fmt("unclassified heads never match %s = %d", face3d::trait_title(t), v));
                flt.sel[kSkin3d + t] = kAny;
            }
        flt.sel[kSkin3d] = kUnclassified;
        CHECK(!matches(heads[0], flt) && matches(heads[3], flt) && matches(heads[4], flt), "'not classified yet': only the heads without a look");
        flt.clear();
        flt.sel[kSkin] = 20;  // a database facet the chooser hides with 3D looks
        drop_hidden(flt, true);
        CHECK(flt.sel[kSkin] == kAny && !flt.active(), "hidden facets do not filter");
        // counts: every group of the trait (0 for the groups no head has), at most 5; heads without a look are no choice
        flt.clear();
        std::vector<Count> skins = facet_counts(heads, pool, flt, kSkin3d);
        const size_t light = size_t(facet_key(kSkin3d, face3d::kSkinLight)), dark = size_t(facet_key(kSkin3d, face3d::kSkinDark));
        const size_t olive = size_t(facet_key(kSkin3d, face3d::kSkinOlive));
        CHECK(skins.size() == size_t(group_count3d(kSkin3d)) && skins.size() <= size_t(kMaxBuckets) && skins[light].n == 2 && skins[light].sample == 0 &&
                  skins[dark].n == 1 && skins[olive].n == 0 && skins[olive].sample == kNoSample && skins.back().key != kUnclassified,
              fmt("skin counts (%zu groups)", skins.size()));
        std::vector<Count> types = facet_counts(heads, pool, flt, kHairType3d);
        CHECK(types.size() == size_t(kMaxBuckets), "12 hair types in 5 groups");
        flt.sel[kGender] = 1;  // female: 3 (looked) and 5 (not yet)
        std::vector<Count> heads_wear = facet_counts(heads, pool, flt, kHeadwear3d);
        CHECK(heads_wear.size() == face3d::kHeadwearCount && heads_wear[face3d::kHeadband].n == 1 && heads_wear[face3d::kNoHeadwear].n == 0 &&
                  heads_wear.back().key == face3d::kHat,
              "counts under the other filters");
        std::vector<Count> looked_only = facet_counts(heads, {0, 1, 2}, Filter(), kHeadwear3d);
        CHECK(looked_only.size() == face3d::kHeadwearCount && looked_only.back().key == face3d::kHat,
              "no 'not classified yet' choice");
        // tooltip
        const std::string t1 = head_traits(heads[0], true), t4 = head_traits(heads[3], true), tdb = head_traits(heads[0], false);
        CHECK(t1.find("\n3D look: light skin, dark brown short wavy hair, short beard (dark brown), no headwear") == 0 &&
                  t1.find("\nGender: Male") != std::string::npos && t1.find("\nEyes (database): Brown") != std::string::npos &&
                  t1.find("Ethnicity (database)") != std::string::npos && t1.find("Caucasian 2") == std::string::npos,
              t1);
        CHECK(t4.find("\n3D look: not classified yet") == 0, t4);
        CHECK(tdb.find("3D look") == std::string::npos && tdb.find("\nSkin tone: Caucasian 2") != std::string::npos, tdb);
        CHECK(kOnly3dDefaultMin == 200, "'Only heads with a 3D look' starts on from 200 looks");
        // managers (no looks, never set_look): 3D facets have no value, database filters as before
        Face m;
        m.manager = true;
        m.raw[kSkin] = 30;
        Filter mf;
        mf.sel[kSkin] = facet_key(kSkin, 30);
        CHECK(matches(m, mf) && m.raw[kSkin3d] == kNoValue && head_traits(m, false).find("Skin tone: Caucasian 3") != std::string::npos,
              "manager heads keep the database facets");
    });
}
